def minimumOperations(nums: List[int], target: List[int]) -> int:
    d = [t - n for t, n in zip(target, nums)]
    ans = abs(d[0])
    for i in range(1, len(d)):
        a, b = d[i - 1], d[i]
        if (a >= 0) == (b >= 0) or a == 0 or b == 0:
            if abs(b) > abs(a):
                ans += abs(b) - abs(a)
        else:
            ans += abs(b)
    return ans
